["A group leader may select this option to add the entire group to the battleground queue. Your group will enter the battleground at the same time."]="队伍领袖可以选中此选项，将整个队伍加入战场队列。你的队伍将同时进入战场。",
["A guy walked up to me and said, \"I'm a teepee, I'm a wigwam, I'm a teepee, I'm a wigwam.\"  I said, \"Relax, man, you're too tense.\""]="有个人走到我面前说：\"我是帐篷，我是棚屋，我是帐篷，我是棚屋。\" 我回答说：\"放松点，老兄，你太紧张了。\"",
["A list of all the active quests you currently have. You can have up to 25 active quests at one time."]="列出你当前接取的所有任务。你最多可以同时拥有 25 个进行中的任务。",
