["A proud member of the Alliance, opposed to members of the Horde (Orcs, Trolls, Tauren, Undead, Blood Elves)."]="骄傲的联盟成员，与部落成员（兽人、巨魔、牛头人、亡灵、血精灵）为敌。",
["A proud member of the Horde, opposed to members of the Alliance (Night Elves, Dwarves, Humans, Gnomes, Draenei)."]="骄傲的部落成员，与联盟成员（暗夜精灵、矮人、人类、侏儒、德莱尼）为敌。",
["A quest giver with a gray '!' over its head has a quest that you are too low level to accept. Check back once you gain a few levels."]="头顶灰色 '!' 的任务给予者拥有的任务等级高于你。等你升几级后再来找他。",
