["Adds a player to your ignore list. You will no longer see messages or other text from players on your ignore list, nor will these players be able to communicate with you in any other way."]="将一名玩家加入你的屏蔽名单。你将不再看到屏蔽名单中玩家的消息或其他文本，他们也同样无法以任何方式与你交流。",
