["Each of the 21 gray bars below should be distinct from one another. Adjust the gamma slider until you can distinguish between each shade of gray. If using the slider alone is not enough to achieve this, adjust your monitor's brightness and contrast settings until satisfied."]="下方 21 条灰色色带应彼此可区分。调整亮度校正滑块，直到你能分辨出每一种灰色深浅。如果仅靠滑块无法做到，请调整显示器的亮度与对比度设置，直到满意为止。",
["Each time you assist in killing a civilian in PvP that is too low of a level to give you experience (a gray level number), you will get a dishonorable kill.   Each dishonorable kill you get immediately reduces your overall ranking slightly, and each additional dishonorable kill you get during a single day has a larger effect than the last one.   Dishonorable kills are directly applied to your ranking."]="每次你在 PvP 中参与击杀一名等级过低、无法给予你经验值（等级数字为灰色）的平民时，都会获得一次非荣誉击杀。每次非荣誉击杀都会立即略微降低你的总排名，而同一天内每多一次非荣誉击杀，其影响都会比上一次更大。非荣誉击杀会直接作用于你的排名。",
["Each time you or a group you are part of does damage to an enemy player in PvP that is subsequently killed you gain an honorable kill.   You only get an honorable kill if the target’s difficulty is green or better (the target would give you experience if it were a monster).    Only enemy players give honorable kills."]="每次你或你所在的小队在 PvP 中对一名敌方玩家造成伤害，且该玩家随后被击杀时，你都会获得一次荣誉击杀。只有当目标难度为绿色或更高（若其为怪物则会给予你经验值）时，你才能获得荣誉击杀。只有敌方玩家才能带来荣誉击杀。",
["Each victory subsequent to the first each day will earn you:"]="每天第一场胜利之后的每场胜利都将为你赢得：",
