["Enable mature language filtering.\n\n|cffff0000Warning:|r Battle.net is unavailable, so this setting may not be saved."]="启用成人语言过滤。\n\n|cffff0000警告：|r Battle.net 不可用，因此此设置可能无法保存。",
["Enable the playing of alert sounds when aggro advances to a higher level."]="当仇恨提升到更高等级时播放警报音效。",
