["Enable this option if you have a World of Warcraft Gaming Mouse and you wish to bind keys to the extra buttons."]="如果你拥有《魔兽世界》游戏鼠标并希望为额外按键绑定按键，请启用此选项。",
["Enable this to have Battle.net system messages appear in a popup window."]="启用此选项可让 Battle.net 系统信息在弹出窗口中显示。",
["Enable this to prevent resizing the game window."]="启用此选项可防止调整游戏窗口大小。",
["Enable to allow sounds to play even when World of Warcraft is in the background."]="启用后，即使《魔兽世界》在后台运行也会播放声音。",
["Enable to continuously play background music."]="启用后可连续播放背景音乐。",
["Enables a full screen effect that softens edges and lighting. Disabling this can sometimes improve performance."]="启用一种柔化边缘与光照的全屏效果。禁用它有时可提升性能。",
["Enables all pixel shaders."]="启用所有像素着色器。",
["Enables character shadows for all characters within the game.  Disabling this can sometimes improve performance."]="为游戏中的所有角色启用角色阴影。禁用此选项有时可提升性能。",
["Enables high quality filtering of texture maps. Turn this feature off to increase performance."]="启用纹理贴图的高质量过滤。关闭此功能可提升性能。",
["Enables or disables all sound."]="启用或禁用所有声音。",
["Enables or disables game sound effects."]="启用或禁用游戏音效。",
["Enables reverb sound effects.  This will affect performance."]="启用混响音效。这会影响性能。",
["Enables software emulation for headphone surround sound."]="启用耳机环绕声的软件模拟。",
["Enables specular highlights on terrain. Disabling this can sometimes improve performance."]="启用地形的高光反射。禁用此选项有时可提升性能。",
["Enables speech from errors (e.g. \"Target out of range\")."]="启用错误语音提示（例如\"目标超出范围\"）。",
["Enables speech from groupmates."]="启用队友语音。",
["Enables stereoscopic (3D) video."]="启用立体（3D）视频。",
["Enables subtitles during the intro cinematic."]="在开场动画期间启用字幕。",
["Enables the projecting of textures to the environment. Disabling this may greatly improve performance."]="启用向环境投射纹理。禁用此选项可大幅提升性能。",
["Enables the use of hardware for 3D sound management. This may alter your sound performance."]="启用硬件进行 3D 声音处理。这可能会改变你的声音性能。",
["Enables the use of vertex shaders to speed animation. Enable this to maximize performance."]="启用顶点着色器以加速动画。启用此选项可获得最佳性能。",
["Enables triple buffering of frames when vertical sync is enabled. Selecting triple buffering may even out frame rate spikes, but may also cause slight input lag."]="在启用垂直同步时启用三倍帧缓冲。选择三倍缓冲可以平缓帧率波动，但也可能导致轻微的输入延迟。",
["Enables your microphone."]="启用你的麦克风。",
["Enabling Simple Chat will cause your chat window settings to be lost. Are you sure you want to enable Simple Chat?"]="启用简易聊天将导致你的聊天窗口设置丢失。你确定要启用简易聊天吗？",
