["Honor is gained by killing members of the opposite faction in PvP combat. You can use honor points to purchase special items."]="在 PvP 战斗中击杀敌对阵营成员即可获得荣誉。你可以用荣誉点数购买特殊物品。",
["Honor is what you gain by making honorable kills in PvP combat.   How much honor you gain per kill is determined by how much damage you (or your group) did to the player that was killed, with more damage done equaling more honor.   This honor gain is split amongst the members of your group or raid group.   Also you will gain less honor for killing the same player over and over again in a short period of time, so after a few kills of the same player you will get little or no honor from killing them."]="荣誉来自你在 PvP 战斗中取得的荣誉击杀。每次击杀能获得多少荣誉，取决于你（或你的小队）对被击杀玩家造成的伤害，伤害越高获得的荣誉越多。获得的荣誉会在小队或团队成员之间分配。此外，短时间内反复击杀同一名玩家所获得的荣誉会减少，因此在连续击杀同一名玩家几次之后，你将几乎无法从中获得荣誉。",
