["How are you?"]="你好吗？",
["How does a Tauren hide in a cherry tree?  He paints his hooves red."]="牛头人怎么躲在樱桃树上？把蹄子涂成红色就行了。",
["How generous."]="真大方。",
["How kind of you."]="你真好心。",
["How much memory your AddOns are using. You can get to the addon management page from the character select screen."]="你的插件占用了多少内存。你可以从角色选择界面进入插件管理页面。",
["How you doing?"]="你怎么样？",
["How's it hanging?"]="最近怎么样？",
["Hunters require focus to use their abilities.  Focus generates while standing still."]="猎人使用技能需要集中值。站立不动时会生成集中值。",
["Hurry, fire!"]="快，开火！",
["I am in your debt."]="我欠你个人情。",
["I apologize profusely for any inconvenience my murderous rampage may have caused."]="对于我这场杀戮狂欢可能造成的任何不便，我深表歉意。",
["I be feeling you."]="我懂你。",
["I be in a bad way!"]="我情况不妙！",
["I be in a bad way."]="我情况不妙。",
["I be needing more mana!"]="我需要更多法力！",
["I believe so."]="我想是的。",
["I can fulfill the role of:"]="我可以担任以下角色：",
["I can't find anywhere to get my nails done."]="我找不到地方做指甲。",
["I can't stand the smell of Orcs."]="我受不了兽人的味道。",
["I can't wait till this quest is done, and I can look for another Garibaldi artifact."]="我迫不及待想完成这个任务，好去寻找另一件加里波第神器。",
["I can't wait to suck the juice out of your eyeballs."]="我等不及要把你的眼珠吸干了。",
["I come from the Orcs.  We eat with spoons and forks.  We love to eat our pork."]="我来自兽人。我们用勺子和叉子吃饭。我们爱吃猪肉。",
["I dig it."]="我喜欢。",
["I do hope to find some interesting gadgets around here.  I do love tinkering with things."]="我真希望能在这一带找到些有趣的小玩意儿。我最喜欢摆弄东西了。",
["I do not find you completely disagreeable."]="我觉得你还不算太讨厌。",
["I don't care that much about romance.  I fell in love before, and look what happened to me."]="我不太在乎什么浪漫。我以前也恋爱过，看看我落得什么下场。",
["I don't drink anymore.  'Course, I don't drink any less, either."]="我已经不再多喝了。当然，也没少喝。",
["I don't feel that the 1 to 10 scale is fine enough to capture subtle details of compatibility.  I'd prefer a 12 dimensional compatibility scale with additional parameters for mechanical aptitude and torque."]="我觉得 1 到 10 分的评分标准不足以体现契合度的细微差别。我更希望有一套十二维契合度评分标准，并附带机械天赋和扭矩的额外参数。",
["I don't have a drinking problem.  I drink, I get drunk, I fall down, no problem."]="我没有酗酒问题。我喝酒、喝醉、摔倒，一点问题都没有。",
["I don't know about you, but I can't understand a thing those Wisps say.  I usually just nod."]="不知道你怎么想，反正我一句也听不懂那些小精灵在说什么。我通常就点点头。",
["I don't like to be underground.  It reminds me of death."]="我不喜欢待在地下。那会让我想到死亡。",
["I don't mind the Gnomes, but I'm always worried about tripping over one."]="我不讨厌侏儒，但总担心会被他们绊倒。",
["I don't need to get funky.  I'm already there."]="我不需要变得多酷。我已经够酷了。",
["I don't smell that bad for a dead dude, do I?"]="作为一个死人，我身上味道不算太糟吧？",
["I don't think so."]="我不这么认为。",
["I feel pretty, oh so pretty (spit)."]="我觉得自己很美，哦，太美了（吐口水）。",
["I feel very feminine, and I'll beat the crap out of anyone who disagrees."]="我觉得自己很有女人味，谁敢不同意我就揍扁谁。",
["I give myself a Dutch oven pedicure every night.  I've got no foot fungus at all.  My toes are pristine."]="我每晚都在闷罐里给自己做足部护理。我一点脚气都没有。我的脚趾干干净净。",
["I got a shrunken head.  I just came out of the pool."]="我的脑袋缩水了。我刚从泳池里出来。",
["I got all this and personality, too."]="我不只有这副身板，还有个性。",
["I had an idea for a device that you could put small pieces of bread in to cook, but in the end I really didn't think there would be much of a market for it."]="我曾想设计一种能放小片面包进去烤的装置，但最后我觉得那东西根本没什么市场。",
["I have a number of inventions I'd like to show you back at my place."]="我有些发明想请你去我那儿看看。",
["I have no respect for people with small piercings.  I say go full hog.  Put a spear through your head."]="我瞧不起那些只打小孔的人。要我说就该玩大的。往脑袋里插根长矛吧。",
["I heard a knee slapper once, and skipped my kneecap right across a lake."]="我听过一个好笑的笑话，笑得膝盖骨都蹦到湖对岸去了。",
["I heard if you cut off an extremity, it'll regenerate a little bigger.  Don't believe it."]="我听说砍掉一肢，再长出来会大一点。别信。",
["I hope you're not afraid of snakes."]="希望你不怕蛇。",
["I hope you're well rested.  You're going to need your strength."]="希望你休息好了。你会需要体力的。",
["I kill two dwarves in the morning, I kill two dwarves at night.  I kill two dwarves in the afternoon, and then I feel alright. I kill two dwarves in time of peace and two in time of war. I kill two dwarves before I kill two dwarves, and then I kill two more."]="我早上杀两个矮人，晚上杀两个矮人。下午再杀两个矮人，然后我就舒坦了。和平时杀两个矮人，战时也杀两个矮人。杀两个矮人之前先杀两个矮人，然后我再杀两个。",
["I know.  My natural beauty is intimidating."]="我知道。我天生的美貌让人望而生畏。",
["I lead the way."]="我来带路。",
["I like large posteriors, and I cannot prevaricate."]="我喜欢大屁股，而且我无法说谎。",
["I like men who aren't afraid to cry; cry uncle."]="我喜欢不怕哭的男人；哭吧，认输吧。",
["I like my ale like I like my men; dark and rich."]="我喜欢我的麦酒，就像喜欢我的男人：又黑又醇。",
["I like my beer like I like my women; stout and bitter."]="我喜欢我的啤酒，就像喜欢我的女人：醇厚而苦涩。",
["I like my women dumpy and droopy with halitosis."]="我喜欢矮胖、松垮还有口臭的女人。",
["I like tall men."]="我喜欢高个子男人。",
["I like to fart in the tub."]="我喜欢在浴缸里放屁。",
["I look bigger in those mirrors where things look bigger."]="照那种会把人放大的镜子时，我看起来大多了。",
["I love you like a fat kid loves cake."]="我爱你，就像胖小孩爱蛋糕。",
["I must be asleep, cause you're a dream come true.  Also, I'm slightly damp."]="我一定是在做梦，因为你美梦成真了。而且，我身上有点湿。",
["I need a hero."]="我需要一位英雄。",
["I need healing!"]="我需要治疗！",
["I need healing."]="我需要治疗。",
["I need help!"]="我需要帮助！",
["I need mana!"]="我需要法力！",
["I need more mana!"]="我需要更多法力！",
["I need some mana!"]="我需要一些法力！",
["I need to get my chest waxed again."]="我又该给胸口脱毛了。",
["I once laughed so hard, I milked all over the floor."]="我有一次笑得太厉害，奶都喷了一地。",
["I owe you one."]="我欠你一个人情。",
["I require aid!"]="我需要帮助！",
["I suppose so."]="我想是吧。",
["I thank you."]="谢谢你。",
["I think that guys just use the Emerald Dream as an excuse to avoid calling me back."]="我觉得男人们只是拿翡翠梦境当借口，好不回我电话。",
["I think that last vendor short changed me.  Oh, that was a bad one."]="我觉得上次那个商人少找我钱了。噢，这笑话真烂。",
["I want a man with soft hands.  Preferably four of them."]="我想要一个双手柔软的男人。最好是四只手。",
["I will crush and destroy and... ooo... shiny..."]="我要碾碎、摧毁……哦……好闪亮……",
["I will lead the way."]="我来带路。",
["I will return the favor."]="我会报答你的。",
["I wish you well."]="祝你好运。",
["I won't bite you where it shows."]="我不会咬你露在外面的地方。",
["I won't fall for any bad pickup line.  You've got to try two or three, at least."]="我可不会随便被一句搭讪就打动。你至少得试上两三次。",
["I won't forget this."]="我不会忘记这件事的。",
["I would expect the same."]="我也会这样期待。",
["I would like to join a group"]="我想加入一个小队",
["I'd like to give a shout out to my boys in Gnomeregan.  Keeping it real Big-T, Snoop-Pup, and Little Dees.  Y'all are short, but you're real, baby."]="我要向我在诺莫瑞根的兄弟们致敬。大 T、嗅探犬和小迪斯，保持真我。你们个子虽矮，但够真实，宝贝。",
["I'd like to see you in a kilt."]="我想看你穿苏格兰短裙。",
["I'd paint my toenails, but I'm not sure where they fell off."]="我倒是想涂脚趾甲，可我不知道它们掉哪儿了。",
["I'll always treasure our time together."]="我会永远珍惜我们共度的时光。",
["I'll give you crazy love."]="我会给你疯狂的爱。",
["I'll have you know I can flatten steel with my thighs."]="告诉你，我可以用大腿把钢铁压扁。",
["I'll lead the way."]="我来带路。",
["I'll miss you."]="我会想你的。",
["I'm a force of nature."]="我是自然之力。",
["I'm also looking for a group for:"]="我也在寻找小队，目标是：",
["I'm dead, and I'm pissed."]="我死了，而且我很恼火。",
["I'm in a rotten mood."]="我心情糟透了。",
["I'm looking for a group for:"]="我在寻找小队，目标是：",
["I'm out of mana!"]="我的法力用光了！",
["I'm short on mana!"]="我的法力不多了！",
["I'm the type of girl my mother warned me about."]="我就是我妈警告过我的那种女孩。",
["I'm tired of the same old bull."]="我受够了这些老一套的废话。",
["I've discovered that getting pummeled by a blunt weapon can be quite painful."]="我发现被钝器狠揍一顿是相当疼的。",
["I've got big soulful eyes, long eyelashes, and a wet tongue.  What more could a guy want?"]="我有深情的大眼睛、长长的睫毛和湿润的舌头。男人还能想要什么？",
["I've got no mana!"]="我没有法力了！",
["IM Style"]="即时通讯风格",
["INTERNAL ERROR, DISMOUNTING A NON-PET"]="内部错误：正在解散非宠物单位",
["INTERNAL ERROR, YOU DON'T HAVE A PET TO DISMOUNT"]="内部错误：你没有可解散的宠物",
["Icon"]="图标",
["Icon Color"]="图标颜色",
["Icons in Chat"]="聊天中的图标",
["If I said you had a good body, would you hold it against me?"]="如果我说你身材不错，你会因此记恨我吗？",
["If I wasn't purple, you'd see I was blushing."]="要不是我皮肤是紫色的，你就能看到我脸红了。",
["If cannibalism be wrong, I don't want to be right."]="如果吃人是错的，那我宁愿不要正确。",
["If checked, invitees whom respond to this event will have their status approved automatically; otherwise, you will have to approve them manually."]="若勾选此项，回应此活动的受邀者将自动获得批准状态；否则你需要手动批准他们。",
["If checked, invitees will be unable to respond to this event."]="若勾选此项，受邀者将无法回应此活动。",
["If enabled, you will be able to look at your map to see the locations of certain quest objectives."]="启用后，你可以查看地图以了解某些任务目标的位置。",
["If enabled, you will be able to review your talents in the Talent Interface before spending your talent points."]="启用后，你可以在花费天赋点数之前，先在天赋界面中查看你的天赋。",
["If enabled, you will only be able to receive loot by looting quest items, looting items that everyone passes on, or being given loot by the master looter."]="启用后，你只能通过拾取任务物品、拾取所有人放弃的物品，或由战利品分配者分配来获得战利品。",
["If enabled, your character will automatically dismount before casting while flying."]="启用后，你的角色在飞行中施法前会自动下坐骑。",
["If enabled, your character will automatically switch between auto attack and auto shot."]="启用后，你的角色会自动在自动攻击与自动射击之间切换。",
["If rot was hot, I'd be a volcano."]="如果腐烂算性感，那我就是一座火山。",
["If the Name Plate is displayed for your current target, show the enemy cast bar with the target's health bar in the game field."]="如果当前目标显示了姓名板，则在游戏画面中于目标生命条处显示敌方施法条。",
["If the sole purpose or intent of any action is to continually upset, aggravate, or otherwise annoy another player, that action may be considered physical harassment or �grief play�.  Before reporting physical harassment, make sure that the situation that is being petitioned falls outside the realm of the PvP policy (www.worldofwarcraft.com/policy/pvp.shtml). "]="如果任何行为的唯一目的或意图是持续扰乱、激怒或以其他方式骚扰另一名玩家，该行为可能被视为人身骚扰或“恶意骚扰”。在举报人身骚扰之前，请确认所申诉的情形不属于 PvP 政策（www.worldofwarcraft.com/policy/pvp.shtml）的范畴。",
["If there is another player you have enjoyed playing with, add them to your friends list! Click on the |cffffd200Social Button|r and add them to your list of friends.|n|nYou can only add friends from your own realm."]="如果有其他玩家与你相处愉快，就把他们加进好友列表吧！点击|cffffd200社交按钮|r，将他们加入你的好友列表。|n|n你只能添加自己服务器上的好友。",
["If this is checked, sound will be recorded in the movie."]="若勾选此项，视频中将录制声音。",
["If this is checked, the game will offer the choice of compressing, ignoring, or deleting any pending movies when you log in."]="若勾选此项，你登录时游戏会提供选项，让你压缩、忽略或删除待处理的视频。",
["If this is checked, the movie will be compressed when you stop recording. Otherwise, you will need to use the compress button to finish processing the movies."]="若勾选此项，停止录制时视频将被压缩。否则，你需要使用压缩按钮来完成视频处理。",
["If this is checked, you will see a movie camera icon appear on the minimap frame while recording. If the user interface is recorded, this will also appear in the movie."]="若勾选此项，录制期间你会看到小地图边框上出现摄像机图标。如果录制了界面，该图标也会出现在视频中。",
["If this is checked, you will see the cursor in the movie. Regardless of this setting, you will see the cursor while playing."]="若勾选此项，视频中将显示光标。无论此设置如何，游玩时你都能看到光标。",
["If this is checked, you will see the user interface in the movie. Regardless of this setting, you will see the user interface while playing."]="若勾选此项，视频中将显示用户界面。无论此设置如何，游玩时你都能看到用户界面。",
["If you are the leader of a group, this button will add your current group to the battleground queue. Your group will be guaranteed to get into the same battleground instance at the same time.  Any group member added after you click this button or a group member in a queue for another battleground will not be guaranteed entrance to the same battleground."]="如果你是队长，此按钮会将你当前的小队加入战场队列。你的小队将保证同时进入同一战场副本。在你点击此按钮之后加入的小队成员，或已在其他战场队列中的小队成员，将无法保证进入同一战场。",
["If you belong to a party, you can right-click your portrait to bring up the Party Options menu. This menu will allow you to quit the party or see what looting rules the party is using. A party leader can add or remove party members, as well as change the party's looting rules."]="如果你属于某个小队，可以右键点击自己的头像打开小队选项菜单。通过该菜单你可以退出小队，或查看小队当前使用的战利品规则。队长可以添加或移除小队成员，也可以更改小队的战利品规则。",
["If you defeat an enemy and see sparkles on its corpse, that means it has loot.|n|n|cffffd200Right Click|r on a creature's corpse to loot it. This will open a loot window. Then |cffffd200Right Click|r on any items in that window to move them to your backpack."]="如果你击败敌人后看到其尸体上有闪光，就说明它有战利品。|n|n|cffffd200右键点击|r生物的尸体即可拾取。这会打开战利品窗口。然后|cffffd200右键点击|r窗口中的任意物品，将其移入你的背包。",
["If you find yourself stuck and unable to move, please try the auto-unstuck feature prior to petitioning a GM. In most cases, this should solve the problem. Activating the auto-unstuck command will first attempt to use your hearthstone to port you back to your inn. If this is not possible, it will attempt to nudge your character out of position.\n\nPlease note this option can only be used every 5 minutes. Using the auto-unstuck option will log your character and location so that we can verify and fix the location in the future."]="如果你发现自己卡住无法移动，请在向 GM 求助之前先尝试自动脱困功能。多数情况下这能解决问题。启用自动脱困命令后，会首先尝试用你的炉石将你传送回旅店。如果无法做到，则会尝试将你的角色推出当前的位置。\n\n请注意，此选项每 5 分钟只能使用一次。使用自动脱困选项会记录你的角色与位置，以便我们日后核实并修复该位置。",
["If you replace this item, the following stat changes will occur:"]="如果你替换此物品，将发生以下属性变化：",
["If you stray into deep and uncharted waters, you will see a Fatigue bar. If you become completely fatigued, you will begin to drown."]="如果你误入深邃未知的水域，就会出现疲劳条。当疲劳条完全耗尽时，你会开始溺水。",
