["Increases all characters’ chance to Critical Hit. The|namount of the bonus is higher per point on Rogues than|nother classes. Agility affects dodge. Rogues get more|nDodge per point of Agility than other classes. Agility|nadds directly to Armor."]="提高所有角色的爆击几率。潜行者|n每点属性获得的加成高于|n其他职业。敏捷影响躲闪。潜行者每点敏捷获得的|n躲闪高于其他职业。敏捷|n直接增加护甲。",
