["Increases attack power with both melee and ranged weapons, and improves the chance to score a critical hit with all weapons.|nIncreases armor and chance to dodge attacks."]="提高近战与远程武器的攻击强度，并提高所有武器造成爆击的几率。|n提高护甲与躲闪攻击的几率。",
["Increases attack power with melee weapons.\nIncreases the amount of damage that can be blocked with a shield."]="提高近战武器的攻击强度。\n提高可用盾牌格挡的伤害量。",
["Increases attack power with ranged weapons.|nImproves chance to score a critical hit with all weapons.|nIncreases armor and chance to dodge attacks."]="提高远程武器的攻击强度。|n提高所有武器造成爆击的几率。|n提高护甲与躲闪攻击的几率。",
