["Raids are groups of more than 5 people and are typically used to defeat unique challenges at high levels.\n\n|cffffffff- Raid members cannot earn credit toward most non-raid quests. Specifically, they will not receive non-raid quest credit for killing creatures or collecting items.\n\n- Raids grant substantially less experience for defeating monsters than normal groups.\n\n- Raids allow you to overcome challenges that might otherwise be nearly impossible.|r"]="团队是超过 5 人的队伍，通常用来挑战高等级特有的难关。\n\n|cffffffff- 团队成员无法获得大多数非团队任务的进度。具体来说，击杀生物或收集物品时都无法获得非团队任务的进度。\n\n- 与普通小队相比，团队击杀怪物获得的经验大幅减少。\n\n- 团队可以让你完成独自几乎不可能完成的挑战。|r",
