["Rank is the final result of all the honor system calculations.  Based upon a comparison between your standing for the week versus your current rank, your rank may either rise, fall, or stay the same.  Higher level players rise more quickly in rank (and fall more slowly) than lower level players.  In addition, rank increases more quickly at low ranks than at high ranks."]="军衔是荣誉系统所有计算的最终结果。根据你这周的排名与当前军衔的对比，你的军衔可能上升、下降或保持不变。高等级玩家晋升军衔比低等级玩家更快（且下降更慢）。此外，低军衔时的晋升速度快于高军衔。",
