["So, I have this idea for a great movie.  It's about two Gnomes who find a bracelet of power, and they have to take it to the Burning Steppes and cast it into The Cauldron.  They form the Brotherhood of the Bracelet.  Along the way, they're trailed by a murloc named Gottom who's obsessed with the bracelet, and nine bracelet bogeymen.  It could be a three parter called \"Ruler of the Bracelet\".  The first part would be called \"The Brotherhood of the Bracelet\", followed by \"A Couple of Towers\", with the climactic ending called \"Hey, the King's Back\"."]="\"我有个拍大片的好点子。讲的是两个侏儒找到了一只强大的手镯，他们必须把它带到燃烧平原，扔进大熔炉。他们组成了手镯兄弟会。一路上，一个名叫高顿、对手镯痴迷的鱼人跟踪着他们，还有九个想抢手镯的恶棍。我们可以拍成三部曲，叫\"手镯之王\"。第一部可以叫\"手镯兄弟会\"，接着是\"几座塔\"，最后的高潮结局叫\"嘿，国王回来了\"。",
["So, an Orc walks into a bar with a parrot on his shoulder.  The bartender says, \"Hey, where'd you get that?\"  The parrot says, \"Durotar.  They got 'em all over the place.\""]="一个兽人肩上扛着一只鹦鹉走进酒吧。酒保说：\"喂，你从哪儿弄来那玩意儿的？\"鹦鹉回答说：\"杜隆塔尔。那儿到处都是。\"",
["So, you want to fight for the glory of victory in the games? Well, you're going to have to wait. The Steamwheedle Cartel is taking a break after the great excitement of last season! Come back next week for your shot at glory! Feel free to practice in the meantime, but the true fun will have to wait."]="这么说，你想为了比赛中的胜利荣耀而战？那好吧，你得等着。热砂财团在上个赛季的激动人心之后正在休整！下周再来争取你的荣耀机会吧！期间你可以随便练习，但真正的乐趣还得再等等。",
