["The amount of happiness your pet currently has. Content pets inflict normal damage on their enemies, whereas Happy pets inflict enhanced damage, and unhappy pets inflict reduced damage. Happiness goes down when your pet dies or as it grows hungry, while feeding your pet will increase its happiness."]="你的宠物当前拥有的快乐值。满足的宠物对敌人造成正常伤害，快乐的宠物造成更高伤害，而不快乐的宠物造成的伤害降低。宠物死亡或逐渐饥饿时快乐值会下降，而喂养宠物则会提升快乐值。",
