["There is no direct path to that destination!"]="没有通往该目的地的直达路线！",
["There is no movie to compress."]="没有可压缩的视频。",
["There is no taxi vendor nearby!"]="附近没有飞行管理员！",
["There is nobody to eject!"]="没有可驱逐的对象！",
["There is nothing to attack."]="没有可攻击的目标。",
["There were multiple players in the party with that name, please include realm name"]="小队中有多名玩家使用该名字，请注明服务器名称",
["There were no articles matching your search criteria."]="没有符合你搜索条件的物品。",
["There's nothing like sleeping in the forest under the moonlight."]="没有什么比在月光下的森林里入睡更惬意的了。",
["These Settings"]="这些设置",
["These are general gameplay related controls that affect how your character interacts with objects and other players in the game world."]="这些是影响你的角色如何与游戏世界中的物体和其他玩家互动的一般游戏控制选项。",
["These are the factions that you have interacted with."]="这些是你曾经打过交道的阵营。",
["These are the lowest recommended graphics settings for the game. These settings provide excellent performance."]="这些是游戏推荐的最低画质设置。这些设置能提供出色的性能。",
["These are your active talents"]="这些是你当前激活的天赋",
["These controls allow you to modify specific detail levels for many game elements and effects."]="这些控制选项允许你调整许多游戏元素和效果的特定细节等级。",
["These items can't be swapped."]="这些物品无法互换。",
["These options affect whether certain UI and character elements are hidden or displayed."]="这些选项决定某些界面和角色元素是隐藏还是显示。",
["These options affect your character's behaviors in combat, and allow you to change the way combat is displayed in the UI."]="这些选项影响你角色在战斗中的行为，并允许你更改战斗中界面显示的方式。",
["These options allow you to change details having to do with stereoscopic (3D) viewing."]="这些选项允许你更改与立体（3D）视觉相关的细节。",
["These options allow you to change the behavior of the help systems within the game."]="这些选项允许你更改游戏内帮助系统的行为。",
["These options allow you to change the size and detail in which your video hardware renders the game."]="这些选项允许你更改显示硬件渲染游戏时的大小和细节。",
["These options allow you to change the types of Battle.net messages you receive."]="这些选项允许你更改接收到的 Battle.net 消息类型。",
["These options allow you to change the way the mouse behaves inside the game."]="这些选项允许你更改鼠标在游戏中的行为方式。",
["These options allow you to configure the floating combat text which can be displayed in the center of the screen, making it easier to follow battles."]="这些选项允许你配置浮动战斗文字，它可以显示在屏幕中央，让你更容易跟上战斗。",
["These options allow you to control and modify your interactions with other players you encounter in Azeroth."]="这些选项允许你控制和修改与其他玩家互动的方式。",
["These options allow you to control how buffs and debuffs are displayed."]="这些选项允许你控制增益和减益的显示方式。",
["These options allow you to control which names are visible within the game field while you play."]="这些选项允许你控制游戏时游戏场景中显示哪些名称。",
["These options allow you to customize how game objectives like Quests and Achievements are displayed in the user interface,"]="这些选项允许你自定义任务和成就等游戏目标在用户界面中的显示方式，",
["These options allow you to customize the behaviors of the game's quest interface."]="这些选项允许你自定义游戏任务界面的行为。",
["These options allow you to display detailed information on status bars throughout the game."]="这些选项允许你在游戏中的状态条上显示详细信息。",
["These options allow you to enable and disable full game features."]="这些选项允许你启用和禁用完整的游戏功能。",
["These options allow you to modify language settings for the game."]="这些选项允许你修改游戏的语言设置。",
["These options allow you to modify the camera's behavior inside the game."]="这些选项允许你修改游戏内镜头的运行方式。",
["These options can be used to change the display and behavior of party and raid frames within the UI."]="这些选项可用于更改界面中小队和团队框体的显示与行为。",
["These options can be used to change the display and behavior of unit frames within the UI."]="这些选项可用于更改界面中单位框体的显示与行为。",
["These options control sound hardware and input settings for the voice chat system."]="这些选项控制语音聊天系统的声音硬件和输入设置。",
["These options control sound hardware and the types and volumes of sounds within the game."]="这些选项控制声音硬件以及游戏内声音的类型和音量。",
["These options control the ranges and levels of detail used to draw effects and objects in the game."]="这些选项控制绘制游戏效果和物体时使用的范围和细节等级。",
["These settings provide the very best quality and should only be used on high-end systems."]="这些设置提供最佳画质，建议仅在高配置系统上使用。",
["They will speak of your exploits for generations."]="人们会世代传颂你的功绩。",
["This Dungeon is In Progress."]="此地下城正在进行中。",
["This Item Begins a Quest"]="此物品可开启一个任务",
["This Season"]="本赛季",
["This Week"]="本周",
["This achievement has already been completed."]="此成就已经完成过了。",
["This allows you to save sets of equipment. You will then be able to equip a set by clicking on the icon. Once enabled, the Equipment Manager can be accessed through the character frame."]="让你可以保存装备方案。保存后，点击图标即可穿上整套装备。启用后，可从角色窗口中访问装备管理器。",
["This codec is faster to compress than H.264 but it will generate a bigger file. "]="此编解码器压缩速度比 H.264 更快，但会生成更大的文件。",
["This codec is supported natively by Apple devices like the iPod, iPhone and AppleTV. This codec has the best ratio quality/size but it is also the slowest to compress."]="此编解码器原生支持 iPod、iPhone 和 AppleTV 等 Apple 设备。此编解码器具有最佳的质量/体积比，但压缩速度也最慢。",
["This determines how you will interact with members of this faction. If you have at war checked then your default behavior will be to attack them. If you do not have it checked you will not be able to attack them. "]="这决定你与该阵营成员的互动方式。如果勾选了交战，你的默认行为将是攻击他们；如果没有勾选，你将无法攻击他们。",
["This doesn't mean I like you."]="这不代表我喜欢你。",
["This event has already occured."]="此事件已经发生过了。",
["This event is locked."]="此事件已锁定。",
["This guild bank tab is full"]="此公会银行标签页已满",
["This includes information about:  an upcoming patch (what, when, how), upcoming content additions, game play changes, and future rule changes."]="这包括以下信息：即将到来的补丁（内容、时间、方式）、未来的内容更新、游戏性改动以及未来的规则变动。",
["This includes information about:  quests, non-player characters (NPCs), items, locations, or anything else that the player could possibly find out through exploration and/or interaction with the world or other players."]="这包括以下信息：任务、非玩家角色（NPC）、物品、地点，或玩家通过探索和/或与世界或其他玩家互动可能发现的任何其他内容。",
["This is a character you have enjoyed playing with on your realm, You can party and chat with this character."]="这是你在服务器上一起玩得很开心的角色。你可以与该角色交谈并组队。",
["This is a flight master who trains flying beasts to carry passengers from one location to another. For a minimal fee, you can swiftly travel to other flight masters that you have spoken to in the past.|n|nWhen you discover a new city, finding the flight master will allow you to return easily in the future."]="这是一位飞行管理员，他驯养飞行生物来运送乘客往返各地。只需支付少量费用，你就能迅速飞往你以前交谈过的其他飞行管理员处。|n|n当你发现新城市时，找到飞行管理员就能让你日后轻松返回那里。",
["This is a person you know and trust in real life. You will be able to chat with them no matter which Blizzard game you are playing. They must accept your friend invite, at which point your real name will be displayed to all of their friends."]="这是你在现实生活中认识并信任的人。无论你们在玩哪款暴雪游戏，都可以互相交谈。对方必须接受你的好友邀请，之后你的真实姓名就会显示给他们的所有好友。",
["This is a trial version of World of Warcraft. Some features are not available. To experience all of the game go to www.worldofwarcraft.com."]="这是《魔兽世界》的试玩版本。部分功能不可用。要体验完整游戏，请访问 www.wow-europe.com。",
["This is how long you can record a movie before you run out of disk space. The game will stop recording after that time."]="这是在磁盘空间耗尽前你可以录制视频的时长。届时游戏将停止录制并压缩视频。",
["This is how much data needs to be written to your hard drive every second. If the game becomes very choppy while recording then it might be that the data rate is too high for your hard drive. The game will stop recording if it cannot write the data fast enough."]="每秒需要写入硬盘的数据量。如果你在录制时游戏变得非常卡顿，可能是数据速率对你的硬盘来说过高。如果游戏无法足够快地写入数据，就会停止录制。",
["This is true love.  Do you think this happens every day?"]="这才是真爱。你以为这种事天天都会发生吗？",
