["This should be a person you know and trust in real life. You will be able to chat with them no matter which Blizzard game you are playing. If you accept their friend invite your real name will be displayed to all of their friends."]="这应该是一个你在现实生活中认识并信任的人。无论你们在玩哪款暴雪游戏，都可以互相交谈。如果你接受他们的好友邀请，你的真实姓名就会显示给他们的所有好友。",
["This spell may only be used on Helpless Wintergarde Villagers that have not been rescued."]="此法术只能用于尚未被救出的无助的冬卫村民。",
