["This will finish the compression early. You will lose the part that is still not compressed. The part that is currently compressed will be saved on your hard drive."]="这将提前结束压缩。未压缩的部分将会丢失。已压缩的部分将保存到你的硬盘上。",
["This will reset your chat windows to default settings.\nYou will lose any custom settings."]="这会将你的聊天窗口重置为默认设置。\n你将失去所有自定义设置。",
["This will search for uncompressed movies and ask you if you want to compress, delete or ignore them."]="这将搜索未压缩的视频，并询问你是要压缩、删除还是忽略它们。",
