["To create a guild you must purchase this charter, get 9 unique player signatures, and return the charter to me.  Please enter the desired name for your guild."]="要创建公会，你必须购买这份章程，取得 9 名不同玩家的签名，然后把章程交还给我。请输入你想要的公会名称。",
["To create an arena team you must purchase this charter, get the same number of unique player signatures as the size of your team, and return the charter to me.  Please enter the desired name for your arena team."]="要创建竞技场战队，你必须购买这份章程，取得与战队人数相同数量的不同玩家签名，然后把章程交还给我。请输入你想要的竞技场战队名称。",
["To fight enemies, first use |cffffd200Left Click|r to target them. Then click on one of the abilities on the action bar across the bottom of your screen.|n|nYou should use ranged abilities while the target is still far away. Other abilities require you to be close to your target, particularly if your class specializes in melee weapons."]="要与敌人战斗，先用|cffffd200左键点击|r选中他们。然后点击屏幕下方动作条上的技能。|n|n目标距离较远时应使用远程技能。其他技能需要你靠近目标，尤其是当你的职业专精于近战武器时。",
["To free up bag space or make some money you can sell some of the items you have collected.|n|nLocate a vendor and |cffffd200Right Click|r them. Then open your bags and |cffffd200Right Click|r on any items you want to sell."]="要腾出背包空间或赚些钱，你可以出售一些收集到的物品。|n|n找到商人并|cffffd200右键点击|r他。然后打开背包，|cffffd200右键点击|r你想出售的物品。",
["To get started, you should begin a |cffffd200Quest|r.|n|nThere's a quest giver right in front of you. Tutorial tips will help you along the way.|n|nThank you for playing, and good luck in your adventures!"]="作为第一步，你应该先开始一个|cffffd200任务|r。|n|n你面前就有一位任务给予者。教学提示会一步步引导你。|n|n非常感谢你的游玩。祝你在冒险中好运！",
["To my side!"]="到我身边来！",
["To prepare a spell or ability for use, open the Spellbook & Abilities window, left-click the spell or ability and drag it down to your action bar."]="要准备使用某个法术或技能，请打开法术书与技能窗口，左键点击该法术或技能并将其拖到动作条上。",
