["Under free-for-all rules, all group members may loot a monster that they help the group to kill. Money is automatically divided between group members."]="在自由拾取规则下，所有小队成员都可以拾取大家共同击杀的怪物。金钱会自动在小队成员之间分配。",
["Under group loot rules, players take turns looting just like in round-robin with the exception that all group members will be eligible to roll for items over the loot threshold."]="在队伍拾取规则下，玩家轮流拾取尸体，不同之处在于所有小队成员都有资格对超过拾取阈值的物品掷骰。",
["Under master-looter rules, the group leader is the only group member allowed to loot items at or above the threshold. Items below threshold and money are distributed via the round robin rules."]="在队长拾取规则下，只有小队领袖可以拾取达到或超过设定阈值的物品。低于阈值的物品以及金钱按轮流拾取规则分配。",
["Under need-before-greed rules, loot is distributed round-robin style.  Any items over the loot threshold can only be rolled on by group members that can use the item."]="在需求优先规则下，战利品按轮流方式分配。任何超过拾取阈值的物品只有能够使用该物品的小队成员才能掷骰需求。",
["Under round-robin rules, group members take turns looting the monsters that they help the group to kill. Money is automatically divided between group members."]="在轮流拾取规则下，小队成员轮流拾取大家共同击杀的怪物。金钱会自动在小队成员之间分配。",
