["You can eat food to gain health faster. |cffffd200Right Click|r on food to eat it."]="你可以通过进食来更快恢复生命值。|cffffd200右键点击|r食物即可食用。",
["You can enter dungeons or find groups for dungeons by using the |cffffd200Dungeon Finder|r. The Dungeon Finder is accessed from the eye button near the middle of your action bar."]="你可以通过|cffffd200地下城查找器|r进入地下城或寻找地下城队伍。点击动作条中部附近的眼睛按钮即可打开地下城查找器。",
["You can equip items by first clicking the |cffffd200Character Info Button|r near the bottom of the screen, and then the |cffffd200Backpack Button|r at the bottom right of your screen.|n|nThen just drag an equippable item from your backpack onto your character."]="要装备物品，请先点击屏幕底部附近的|cffffd200角色信息按钮|r，然后点击屏幕右下角的|cffffd200背包按钮|r。|n|n接着把背包中可装备的物品拖到你的角色身上即可。",
["You can find your corpse and resurrect at that location. Players that are level 10 or below can resurrect here with no penalty."]="你可以找到自己的尸体并在那里复活。10 级及以下的玩家可以在此复活且不受惩罚。",
["You can go to your class trainer to learn new skills. |cffffd200Right Click|r on trainers to talk to them.|n|nTrainers are found in many towns or cities and always in your starting area. You may have to search around a little to find your trainer."]="你可以前往职业训练师处学习新技能。|cffffd200右键点击|r训练师即可与其交谈。|n|n训练师遍布许多城镇，在你的起始区域也一定有。你可能需要稍微找一找才能找到你想要的训练师。",
["You can invite another player to your group by |cffffd200Right Clicking|r their portrait and selecting the |cffffd200Invite|r option from the popup menu.|n|nYou can leave a group by Right Clicking on your own portrait and choosing the option to leave the party."]="你可以|cffffd200右键点击|r其他玩家的头像，并从弹出菜单中选择|cffffd200邀请|r选项，邀请他们加入你的小队。|n|n你可以右键点击自己的头像并选择离开小队的选项来退出小队。",
["You can learn a new talent in the talent interface.|n|nOpen the talents page by clicking the pulsing |cffffd200Talents Button|r on your action bar."]="你可以在天赋界面中学习新天赋。|n|n点击动作条上闪烁的|cffffd200天赋按钮|r即可打开天赋页面。",
["You can look at your reputation with different groups in the world under the Reputation tab.|n|nClick on the |cffffd200Character Info Button|r to find the Reputation tab."]="你可以在声望标签页中查看你与世界各势力的声望。|n|n点击|cffffd200角色信息按钮|r即可找到声望标签页。",
["You can move spells and abilities to your action bar by clicking the |cffffd200Spellbook & Abilities Button|r at the bottom center of the screen and then dragging the ability icon to your action bar.|n|nYou can also use a spell or ability from the Spellbook directly by clicking on it."]="你可以点击屏幕底部中央的|cffffd200法术书与技能按钮|r，然后将技能图标拖到动作条上，把法术和技能移到动作条。|n|n你也可以直接点击法术书中的法术或技能来使用它。",
