["You have accepted an elite quest. Such quests are best undertaken in a group, for they will take you into areas inhabited by elite creatures.|n|nElite creatures are significantly tougher than normal monsters; however, they are worth more experience. You can tell an elite creature by the golden dragon border around its portrait."]="你接受了一个精英任务。这类任务最好组队完成，因为它们会把你带到同样栖息着精英生物的区域。|n|n精英生物比普通怪物强壮得多，不过击败它们也能获得更多经验值。精英生物的肖像周围有金色的龙形边框，可以借此辨认。",
