["You have attracted the attention of a hostile creature.|n|nA red glow means the creature is attacking you. A yellow glow means you are in danger of being attacked. An orange glow means the creature is attacking you, but may soon change targets."]="你引起了某个敌对生物的注意。|n|n红色光芒表示该生物正在攻击你。黄色光芒表示你随时可能遭到攻击。橙色光芒表示该生物正在攻击你，但随时可能更换目标。",
