["You have completed your first quest! To collect your reward, you need to turn in the quest to a specific quest giver. Usually this is the same questgiver who gave you the quest.|n|nYou can see nearby questgivers as |cffffd200?|r on your minimap in the upper right of your screen. |cffffd200Right Click|r on a quest giver to talk to him or her."]="你完成了第一个任务！要领取奖励，你需要向特定的任务给予者交付任务，通常就是给你任务的那个人。|n|n你可以在屏幕右上角的小地图上看到附近的任务给予者，以 |cffffd200?|r 标示。|cffffd200右键点击|r任务给予者即可与其交谈。",
["You have died.  Release spirit to enter Spectator Mode."]="你已经死亡。释放灵魂以进入观战模式。",
