["You have gained access to the totem bar! You will gain an action button on this bar whenever you gain access to a new totem element.|n|nThis bar can hold one totem spell per totem element. At higher level you will gain the ability to drop multiple totems at once."]="你已获得图腾栏的使用权！每当你获得一种新的图腾元素，该栏位上就会多出一个动作按钮。|n|n该栏位每种图腾元素可放置一个图腾法术。等级提高后，你将获得同时放下多个图腾的能力。",
["You have joined"]="你加入了",
["You have joined a raid group."]="你加入了一个团队。",
["You have joined a raid group: a group with an increased limit of 40 members, though usually 10 or 25. Raid groups are necessary to enter the most challenging dungeons or to defeat the most powerful enemies, typically at high level.|n|n|cffff2020While in a raid group, you will not earn credit towards most quests. To leave a raid group, Right Click on your character portrait and select Leave party.|r"]="你加入了一个团队：团队的人数上限为 40 人，不过通常为 10 人或 25 人。要进入最具挑战性的地下城或击败最强大的敌人（通常在高等级时），就必须组建团队。|n|n|cffff2020在团队中，大多数任务的目标都不会被认定完成。要离开团队，右键点击你的角色头像并选择离开小队。|r",
["You have joined the guild."]="你加入了公会。",
["You have learned a new spell or ability! Use the |cffffd200Spellbook & Abilities Button|r near the bottom of your screen to open your Spellbook. |cffffd200Left Click and drag|r a spell or ability to move it to your Action Bar.|n|nThe Spellbook is organized by category, as indicated by the tabs sticking out from the right side of the book."]="你学会了一个新法术或技能！使用屏幕下方的 |cffffd200法术书与技能按钮|r 打开法术书。|cffffd200左键点击并拖动|r法术或技能，即可将其移到动作条上。|n|n法术书按类别分类，书页右侧突出的标签页标示了这些类别。",
["You have learned everything from that book"]="你已经学完了那本书上的所有内容",
