["You have six different smiles; one for when you're angry, one for when you tear flesh, one for when you chew flesh, one for when you loot bodies, one for when you skin game, and one for when you want to kill something."]="你有六种不同的笑容：一种用于生气时，一种用于撕碎血肉时，一种用于咀嚼血肉时，一种用于搜刮尸体时，一种用于剥取兽皮时，还有一种用于想杀点什么的时候。",
