["You haven't selected a champion"]="你还没有选择勇士",
["You know I have to keep moving at night or I'll disappear."]="你知道的，我夜里必须一直移动，否则就会消失。",
["You know how hard it is to get your groove on with the spirit of your great grandmother looking over you?"]="你知道背上整天跟着曾祖母的灵魂，想放松一下有多难吗？",
["You know those Ancient Protectors in Darnassas?  They're not that old."]="你知道达纳苏斯那些远古守护者吗？他们其实没那么老。",
["You know, I really wish I had a garden where I could put a couple of human statues."]="你知道吗，我真希望有个花园，能在里面摆上几座人类雕像。",
["You know, Taurens are born hunters.  You ever see a Tauren catch a salmon out of a stream?  It really is quite exciting.  And, have you ever seen a Tauren stalk a python?  'Course you haven't.  That's because Taurens are so adept at blending in with their surroundings."]="你知道的，牛头人天生就是猎人。你见过牛头人从溪流里抓鲑鱼吗？那真是相当刺激。还有，你见过牛头人悄悄跟踪巨蟒吗？你当然没见过。那是因为牛头人太擅长融入周围环境了。",
["You know, Wisps are actually pretty useful for personal hygiene."]="你知道吗，小精灵其实对个人卫生挺有用的。",
["You know, older bulls really only have one function."]="你知道的，老公牛其实只有一个用处。",
["You know, once you're dead, nothing smells bad anymore.  Rotten eggs?  No problem.  Dead fish?  Like a spring breeze."]="你知道的，人一死，就再没有什么东西闻起来是臭的了。臭鸡蛋？没问题。死鱼？就像春风一样。",
["You know, squirrels can be deadly when cornered."]="你知道的，松鼠被逼到绝境时也会很致命。",
["You leave the group."]="你离开了小队。",
["You look pretty.  I like your hair.  Here's your drink.  Are you ready now?"]="你真漂亮。我喜欢你的头发。这是你的酒。现在准备好了吗？",
["You look pretty.  Pretty tasty."]="你看起来真漂亮。看着就很好吃。",
["You may find that a solution for your issue has already been posted on the Technical Support Forum, located on the World of Warcraft site at:\n\nwww.worldofwarcraft.com\n\nIf your technical issue is not addressed by the solutions posted there, please contact our Technical Support Department:\n\nBy Phone at:  (949) 955-1382\nBy Web at: http://us.blizzard.com/support/index.xml?gameId=11\nBy Email at:  wowtech@blizzard.com"]="你可能会发现，你的问题已有解决方案发布在《魔兽世界》官网的技术支持论坛上：\n\nwww.worldofwarcraft.com\n\n如果那里发布的方案未能解决你的技术问题，请联系我们的技术支持部门：\n\n电话：(949) 955-1382\n网站：http://us.blizzard.com/support/index.xml?gameId=11\n电子邮件：wowtech@blizzard.com",
["You may not bite other vampires."]="你不能咬其他吸血鬼。",
