["You may not queue for a Dungeon while you are listed in the Raid Browser."]="在团队浏览器中登记时，你不能排队进入地下城。",
["You may not queue for this dungeon."]="你不能排队进入该地下城。",
["You may not queue for this."]="你不能排队参加此内容。",
["You may not queue while one or more of your team members is under the effect of restricted play."]="当你的队伍中有一名或多名成员处于受限游戏状态时，你不能排队。",
["You may not trade an item with a temporary enhancement."]="你不能交易带有临时强化的物品。",
["You may only call down a Wintergarde Gryphon in Wintergarde Keep or the Carrion Fields."]="你只能在温德加德要塞或腐尸平原召唤温德加德狮鹫。",
["You may only call down a stampede on Harold Lane."]="你只能对哈罗德·莱恩召唤奔踏。",
["You may only call for the aid of a Wyrmrest Vanquisher in Wyrmrest Temple, The Dragon Wastes, Galakrond's Rest or The Wicked Coil."]="你只能在龙眠神殿、巨龙废土、加拉克隆安息处或邪恶螺旋请求龙眠镇压者的援助。",
["You may only trade bound items to players that were originally eligible to loot the item"]="你只能把绑定物品交易给当初有资格拾取该物品的玩家",
["You may only trade conjured items to players from other realms"]="你只能把魔法制造的物品交易给其他服务器的玩家",
["You may only use the Pouch of Crushed Bloodspore on Gammothra or other magnataur in the Bloodspore Plains and Gammoth."]="你只能对血孢平原与加莫斯的加莫斯拉或其他猛犸人使用碾碎的血孢囊。",
["You may want to invite other players to team up with you to more easily overcome your enemies.|n|nMany difficult quests can be quickly completed in a group, as quest credit is shared by the group. Moreover, groups earn bonus experience, relative to solo players."]="你可以邀请其他玩家与你组队，从而更轻松地击败敌人。|n|n许多困难任务在组队后都能更快完成，因为小队成员共享任务进度。此外，与单人玩家相比，小队还能获得额外经验值。",
["You move me."]="你打动了我。",
["You must advance to a higher level."]="你必须提升到更高的等级。",
["You must be a guild master to purchase a tabard, but feel free to browse."]="只有公会会长才能购买战袍，不过你可以随意浏览。",
